css:
.d-content-version-preview{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-content-version-preview *,.d-content-version-preview *::before,.d-content-version-preview *::after{box-sizing:border-box}
.d-content-version-preview [hidden]{display:none!important}
.d-content-version-preview .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-content-version-preview .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-content-version-preview label{display:block;margin:8px 0}
.d-content-version-preview input,.d-content-version-preview select,.d-content-version-preview textarea,.d-content-version-preview button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-content-version-preview input:not([type=checkbox]):not([type=radio]),.d-content-version-preview select,.d-content-version-preview textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-content-version-preview button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-content-version-preview button:disabled{opacity:.5;cursor:default}
.d-content-version-preview :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-content-version-preview [aria-invalid=true]{border-color:var(--warn)!important}
.d-content-version-preview .d-scroll{max-width:100%;overflow:auto}
.d-content-version-preview table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-content-version-preview th,.d-content-version-preview td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-content-version-preview caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-content-version-preview progress{width:100%;accent-color:var(--ink)}
.d-content-version-preview pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-content-version-preview h3,.d-content-version-preview p{margin:8px 0}
.d-content-version-preview [aria-pressed=true],.d-content-version-preview [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-content-version-preview .d-grow{flex:1;min-width:100px}
.d-content-version-preview summary{cursor:pointer;padding:6px 0}
.d-content-version-preview ul,.d-content-version-preview ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{const versions={v1:'门口镜头。',v2:'门口镜头，先交代空间。'};const draw=()=>{q('[data-preview]').textContent='只读预览：'+versions[q('[data-version]').value];};q('[data-version]').onchange=draw;q('[data-restore]').onclick=()=>{q('[data-draft]').value=versions[q('[data-version]').value];say('所选历史版本已恢复到本次演示草稿');};draw();})(root, q, qa, say);
}
